# Try to find Department of Labor in the data
def search(obj, path=''):
    if isinstance(obj, dict):
        for k, v in obj.items():
            if 'Labor' in str(k):
                print(f'{path}.{k}: {v}')
            search(v, f'{path}.{k}')
